import { type ParentComponent } from "solid-js";

import { Activatable, ActivatableProps } from "#core/ui-next/components/activatable.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

const SimpleButtonComponent: ParentComponent<ActivatableProps> = (props) => {
	return (
		<Activatable
			{...props}
			class={`border-1 border-accent-5 bg-accent-4 hover\\:bg-accent-5 p-1 m-1 font-title text-base text-accent-1 uppercase tracking-150 ${
				props.class ?? ""
			}`}
			name="SimpleButton"
		>
			<div class="relative flex flex-auto items-center justify-center">{props.children}</div>
		</Activatable>
	);
};

export const SimpleButton = ComponentRegistry.register({
	name: "SimpleButton",
	createInstance: SimpleButtonComponent,
});
